def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) > 300:
                if bid is not None and float(bid) >= 120:
                    rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    tight_supply = supply <= 17
    very_tight_supply = supply <= 15

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    else:
        urgency += 1

    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2

    if very_tight_supply:
        urgency += 2
    elif tight_supply:
        urgency += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if urgency >= 7:
        target = max(150.0, highest_prev + 4.0)
    elif urgency >= 5:
        target = max(110.0, avg_prev * 0.78 + 8.0)
    elif urgency >= 3:
        if highest_prev >= 170:
            target = 52.0 if hp >= 6 and no_water_days == 0 else 118.0
        elif highest_prev >= 140:
            target = 60.0 if hp >= 7 and no_water_days == 0 else 102.0
        else:
            target = max(48.0, highest_prev * 0.72 + 3.0)
    else:
        if rich_aggressive >= 2:
            target = 28.0
        elif highest_prev >= 150:
            target = 34.0
        else:
            target = 42.0

    if day >= 8 and hp <= 5:
        target = max(target, 120.0)
    if day >= 9 and no_water_days >= 1:
        target = max(target, 145.0)

    reserve_floor = 0.0
    if hp > 4 and day < 8:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 5:
        affordable = budget

    bid = min(budget, max(0.0, min(target, affordable if affordable > 0 else budget)))

    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 13
    MY_DAILY_SALARY = 150
    SUPPLY = day_context['supply']
    DAY = day_context['day']
    MY_HP = my_status['hp']
    MY_BUDGET = my_status['budget']
    MY_NO_WATER_DAYS = my_status['no_water_days']
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(MY_BUDGET, MY_DAILY_SALARY * 0.1)

    current_bid = MY_DAILY_SALARY * 0.65

    opponent_bids = []
    desperate_opponents_count = 0
    rich_opponents_count = 0

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev_trace = opp.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                opponent_bids.append(prev_trace['bid'])

            if opp['no_water_days'] > 0 or opp['hp'] <= 2:
                desperate_opponents_count += 1
            if opp['budget'] > MY_DAILY_SALARY * 2:
                rich_opponents_count += 1

    max_opponent_bid = 0
    if opponent_bids:
        max_opponent_bid = max(opponent_bids)

    if max_opponent_bid > MY_DAILY_SALARY * 0.7:
        current_bid = max(current_bid, max_opponent_bid + 5)
    elif max_opponent_bid > MY_DAILY_SALARY * 0.4:
        current_bid = max(current_bid, max_opponent_bid + 2)
    else:
        current_bid = max(current_bid, max_opponent_bid + 1)

    if desperate_opponents_count > len(alive_opponents) / 2:
        current_bid = max(current_bid, MY_DAILY_SALARY * 0.85)

    if rich_opponents_count > 0:
        current_bid = max(current_bid, MY_DAILY_SALARY * 0.75)

    if MY_NO_WATER_DAYS > 0:
        current_bid = MY_DAILY_SALARY * 0.95 + (MY_DAILY_SALARY * 0.03 * MY_NO_WATER_DAYS)
        current_bid = max(current_bid, MY_BUDGET * 0.9)
    elif MY_HP <= 3:
        current_bid = max(current_bid, MY_DAILY_SALARY * 0.9)
    elif MY_HP <= 5:
        current_bid = max(current_bid, MY_DAILY_SALARY * 0.8)

    total_water_needed_by_alive = MY_WATER_REQ
    for opp in alive_opponents:
        total_water_needed_by_alive += opp['water_requirement']

    if SUPPLY < total_water_needed_by_alive:
        scarcity_factor = 1 - (SUPPLY / total_water_needed_by_alive)
        current_bid = max(current_bid, MY_DAILY_SALARY * (0.7 + scarcity_factor * 0.2))
        if SUPPLY <= MY_WATER_REQ + 2:
            current_bid = max(current_bid, MY_DAILY_SALARY * 0.95)
    elif SUPPLY > total_water_needed_by_alive + 5:
        current_bid = min(current_bid, MY_DAILY_SALARY * 0.5)

    if DAY >= EPISODE_DAYS - 2 and MY_HP > 5 and MY_BUDGET > MY_DAILY_SALARY * 2:
        current_bid = max(current_bid, MY_DAILY_SALARY * 0.9)
    if DAY == EPISODE_DAYS and MY_HP > 0:
        current_bid = max(current_bid, MY_DAILY_SALARY * 0.7)

    final_bid = min(MY_BUDGET, current_bid)

    if final_bid < 1 and MY_BUDGET > 0:
        final_bid = min(MY_BUDGET, 1.0)

    final_bid = max(0.0, final_bid)

    return final_bid

