def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If alone, bid low-ish to preserve budget
    if not alive_opps:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.35))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Estimate how many allocations are likely available today
    # (each unit of water is per WATER_REQ; we approximate count)
    est_slots = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if est_slots < 1:
        est_slots = 1

    # Determine pressure from yesterday: if someone was bidding very high, avoid matching.
    # If someone was bidding very low and died, we can safely undercut.
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        min_prev = min(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        max_prev = 0.0
        min_prev = 0.0
        avg_prev = DAILY_SALARY * 0.5

    # Base bid: try to be above the low bidder band but under the high bidder band.
    # Use hp to scale urgency.
    urgency = 1.0
    if my_hp <= 1.0:
        urgency = 1.25
    elif my_hp <= 3.0:
        urgency = 1.12
    elif my_hp >= 7.0:
        urgency = 0.9

    # Medium scenario: aim around 0.75 of Cindy-like bids but not exceeding max_prev.
    # Since Cindy avg ~170 and Bob avg ~64, target ~110-135 when possible.
    target = DAILY_SALARY * 0.78

    # Adjust using yesterday spread
    # If max_prev is high, don't chase; if min_prev is low, slightly above it.
    if max_prev > DAILY_SALARY * 1.1:
        target = min(target, max_prev - 25.0)
    if min_prev > 0.0:
        target = max(target, min_prev + 30.0)

    # If supply is scarce (near MIN_SUPPLY), increase slightly.
    if supply <= float(MIN_SUPPLY) + 0.5:
        target *= 1.08
    elif supply >= float(MAX_SUPPLY) - 0.5:
        target *= 0.95

    bid = target * urgency

    # Ensure bid doesn't exceed budget and doesn't go negative
    bid = max(0.0, min(my_budget, bid))

    # If budget is very low, still try to bid something proportional
    if my_budget <= DAILY_SALARY * 0.2:
        bid = max(0.0, my_budget * 0.85)

    # Final clamp: never exceed a reasonable fraction of budget to avoid bankruptcy
    # (but still allow winning when hp is low)
    if my_hp > 3.0:
        bid = min(bid, my_budget * 0.65)

    return float(bid)
